---@alias gcp.unstable.analyticsadmin_v1alpha.GoogleAnalyticsAdminV1alphaConversionEventCountingMethodEnum "CONVERSION_COUNTING_METHOD_UNSPECIFIED"|"ONCE_PER_EVENT"|"ONCE_PER_SESSION"

