---@alias gcp.unstable.analyticsadmin_v1alpha.GoogleAnalyticsAdminV1alphaPropertyPropertyTypeEnum "PROPERTY_TYPE_UNSPECIFIED"|"PROPERTY_TYPE_ORDINARY"|"PROPERTY_TYPE_SUBPROPERTY"|"PROPERTY_TYPE_ROLLUP"

---@alias gcp.unstable.analyticsadmin_v1alpha.GoogleAnalyticsAdminV1alphaPropertyServiceLevelEnum "SERVICE_LEVEL_UNSPECIFIED"|"GOOGLE_ANALYTICS_STANDARD"|"GOOGLE_ANALYTICS_360"

